import{_ as o,o as d,c,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Matrix-GET-Command.md","filePath":"manual-zh/Matrix-GET-Command.md","lastUpdated":1785684581000}'),p={name:"manual-zh/Matrix-GET-Command.md"};function _(S,e,n,t,r,m){return d(),c("div",null,[...e[0]||(e[0]=[a(`<h4 id="_16-4-9-get-命令" tabindex="-1">16.4.9 <code>GET</code> 命令 <a class="header-anchor" href="#_16-4-9-get-命令" aria-label="Permalink to &quot;16.4.9 \`GET\` 命令&quot;">​</a></h4><pre><code>GET _variable_[(_index_[,_index_])]
    [/FILE={_file_ _|_ *}]
    [/VARIABLES=_variable_ …]
    [/NAMES=_variable_]
    [/MISSING={ACCEPT _|_ OMIT _|_ _number_}]
    [/SYSMIS={OMIT _|_ _number_}].
</code></pre><p><code>READ</code> 命令从 SPSS 系统文件、SPSS/PC+ 系统文件或 SPSS 便携文件读取数值数据到矩阵变量或子矩阵中：</p><ul><li>要将数据读入一个变量，在 <code>GET</code> 后面只指定其名称。该变量无需已经存在；如果已存在，则会被替换。该变量的列数等于 <code>VARIABLES</code> 子命令上指定的变量数，行数等于输入文件中的个案数。</li><li>要将数据读入子矩阵，在 <code>GET</code> 之后指定一个已有变量的名称，后面紧跟一个索引表达式。该子矩阵的列数必须等于 <code>VARIABLES</code> 上的变量数，行数必须等于输入文件中的个案数。</li></ul><p>在 <code>FILE</code> 上指定要读取的文件的名称或句柄。使用 “*”，或省略 <code>FILE</code> 子命令，以从活动文件读取。仅当活动文件已在 <code>MATRIX</code> 之外定义时，才允许从活动文件读取。</p><p>在 <code>VARIABLES</code> 子命令上列出要作为矩阵列读取的变量。该列表可以使用 <code>TO</code> 表示一组变量，或使用 <code>ALL</code> 表示所有变量。如果省略 <code>VARIABLES</code>，则读取所有变量。只能读取数值型变量。</p><p>如果在 <code>NAMES</code> 上指定了一个变量，那么作为数据列读取的变量名称将保存在一个字符串向量中，该向量使用给定名称，并替换具有相同名称的任意已有矩阵变量。变量名被截断为 8 字节。</p><p><code>MISSING</code> 和 <code>SYSMIS</code> 子命令控制对输入文件中缺失值的处理。默认情况下，被读取变量中任何用户缺失或系统缺失的数据都会导致错误，从而阻止 <code>GET</code> 执行。要接受缺失值，在 <code>MISSING</code> 上指定下列设置之一：</p><p><code>ACCEPT</code></p><p>原样接受用户缺失值，不作更改。</p><p>默认情况下，系统缺失值仍然会导致错误。使用 <code>SYSMIS</code> 子命令可更改此处理方式：</p><p><code>OMIT</code></p><p>跳过任何包含系统缺失值的个案。</p><p><em>number</em></p><p>将系统缺失值重新编码为 <em>number</em>。</p><p><code>OMIT</code></p><p>跳过任何包含用户缺失或系统缺失值的个案。</p><p><em>number</em></p><p>将所有用户缺失和系统缺失值重新编码为 <em>number</em>。</p><p><code>SYSMIS</code> 子命令仅在 <code>MISSING=ACCEPT</code> 时生效。</p>`,20)])])}const I=o(p,[["render",_]]);export{l as __pageData,I as default};
